import data from './notes.generated.json'

// Generated by scripts/fetch-notes.mjs from the public portfolio-notes repo.
export const projects = data.projects

export function getProject(slug) {
  return projects.find(p => p.slug === slug)
}

export function getNote(projectSlug, noteSlug) {
  return getProject(projectSlug)?.entries.find(e => e.slug === noteSlug)
}

export function formatDate(iso) {
  const date = new Date(`${iso}T00:00:00Z`)
  if (Number.isNaN(date.getTime())) return iso
  return date.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' })
}
